BEGIN TRANSACTION;
CREATE TABLE terminal_fano_fourfolds_index1_sporadic (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    Equation_degree INTEGER NOT NULL,
    a1 INTEGER NOT NULL,
    a2 INTEGER NOT NULL,
    a3 INTEGER NOT NULL,
    a4 INTEGER NOT NULL,
    a5 INTEGER NOT NULL,
    a6 INTEGER NOT NULL,
    CanonicalClass INTEGER NOT NULL,
    Degree TEXT NOT NULL,
    Degree_dec REAL NOT NULL,
    Type_I_Point TEXT,
    Type_II_Point TEXT,
    Type_III_Point TEXT,
    Type_I_Curve TEXT,
    Type_II_Curve TEXT,
    Type_III_Curve TEXT,
    Point_Basket_size INTEGER,
    Curve_Basket_size INTEGER,
    IsSmooth INTEGER CHECK (IsSmooth IN (0, 1)),
    IsQsmooth INTEGER NOT NULL CHECK (IsQsmooth IN (0, 1)),
    IsTerminal INTEGER NOT NULL CHECK (IsTerminal IN (0, 1)),
    IsCanonical INTEGER NOT NULL CHECK (IsCanonical IN (0, 1)),
    UNIQUE (a1, a2, a3, a4, a5, a6)
);
CREATE INDEX idx_equation_degree ON terminal_fano_fourfolds_index1_sporadic(Equation_degree);
CREATE INDEX idx_is_qsmooth ON terminal_fano_fourfolds_index1_sporadic(IsQsmooth);
CREATE INDEX idx_degree_dec ON terminal_fano_fourfolds_index1_sporadic(Degree_dec);
DELETE FROM "sqlite_sequence";
COMMIT;
